import { buildStudyIndex, filterStudyIndex, isLibrarySaved, LIBRARY_KINDS } from './library.js';
import { STORAGE_KEY, ROLES, CATEGORIES, DEFAULT_STATE, normalizeState, filterQuestions, selectMock, safeUrl, escapeHTML as e } from './core.js';

const paths={home:'Home',library:'Study library',questions:'Question bank',mock:'Mock interview',companies:'Company room',story:'My story',applications:'Job tracker',sources:'Source library',path:'Optional plan'};
const icons={home:'M3 10 12 3l9 7M5 9v11h5v-6h4v6h5V9',path:'M5 4h14v16H5zM9 8h6M9 12h6M9 16h4',book:'M12 6c-3-2-7-2-9-1v14c3-1 6-1 9 1 3-2 6-2 9-1V5c-2-1-6-1-9 1Zm0 0v14',mic:'M9 5a3 3 0 0 1 6 0v6a3 3 0 0 1-6 0V5Zm-3 6a6 6 0 0 0 12 0M12 17v4m-4 0h8',company:'M4 21V5h10v16M14 11h6v10M2 21h20M7 8h4M7 12h4M7 16h4M17 14h1M17 17h1',person:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-2a8 8 0 0 1 16 0v2',case:'M8 6V3h8v3M3 6h18v14H3zM3 12c6 3 12 3 18 0M10 13h4',sources:'M12 3 3 7.5 12 12l9-4.5L12 3ZM3 12l9 4.5 9-4.5M3 16.5 12 21l9-4.5',arrow:'M4 12h16m-6-6 6 6-6 6',left:'M20 12H4m6-6-6 6 6 6',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',check:'m5 12 4 4L19 6',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',save:'M6 3h12v18l-6-4-6 4V3Z',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',spark:'m12 3 2.6 6.4L21 12l-6.4 2.6L12 21l-2.6-6.4L3 12l6.4-2.6L12 3Z',leaf:'M20 3C8 1 2 9 5 16c6 7 16 0 15-13ZM4 21 15 10',calendar:'M5 5h14v16H5zM8 2v6m8-6v6M5 11h14',shield:'m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6l8-4Zm-4 10 3 3 5-6',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8ZM12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',menu:'M4 6h16M4 12h16M4 18h16',close:'m6 6 12 12M6 18 18 6',plus:'M12 4v16M4 12h16',edit:'m15 4 5 5M4 20l4-1L21 6l-5-5L3 14l-1 8',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7',pause:'M8 5v14M16 5v14',play:'m7 4 14 8-14 8V4Z',print:'M6 8V3h12v5M6 17H3V8h18v9h-3M6 14h12v7H6z',info:'M12 11v6m0-10v.1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',target:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0ZM17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0ZM12 12h.01'};
const I=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.leaf}"/></svg>`;
const btn=(text,action,icon='arrow',cls='',attrs='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${e(text)}${I(icon,15)}</button>`;
const link=(text,url)=>safeUrl(url)?`<a class="external" href="${e(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${e(text)} ${I('external',12)}</a>`:e(text);
const option=(values,current)=>values.map(v=>`<option ${v===current?'selected':''}>${e(v)}</option>`).join('');
const pill=(text,cls='')=>`<span class="pill ${cls}">${e(text)}</span>`;
let D,S,storageAvailable=true,toastTimeout,mock=null,timer=null,modalReturnFocus;
let ui={page:'home',company:null,search:'',category:'All topics',difficulty:'All levels',role:'All roles',status:'All questions',pageNumber:1,openQuestion:null,companySearch:'',sourceType:'All sources',menu:false,librarySearch:'',libraryKind:'All material',libraryTopic:'All topics',libraryRole:'All roles',libraryDifficulty:'All levels',libraryMode:'read',libraryExpanded:false,libraryOpen:[],recallIndex:0,recallRevealed:false};
const root=document.querySelector('#app'),modal=document.querySelector('#modal');

function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(S));}catch{storageAvailable=false;toast('Storage is unavailable. Export a backup before leaving.');}}
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>t.classList.remove('visible'),3500);}
function toggleArray(key,id){S[key]=S[key].includes(id)?S[key].filter(x=>x!==id):[...S[key],id];persist();}
function readHash(){const [page,id]=location.hash.slice(1).split('/');ui.page=paths[page]?page:'home';ui.company=ui.page==='companies'&&D.companies.some(c=>c.id===id)?id:null;ui.menu=false;}
function navigate(page){if(location.hash===`#${page}`){readHash();render();window.scrollTo(0,0);}else location.hash=page;}
function sourcesFor(ids){return ids.map(id=>D.allSources.find(s=>s.id===id)).filter(Boolean);}
function sourceLinks(ids){return ids.length?`<div class="sources-line"><span>${I('sources',12)} Read the source</span>${sourcesFor(ids).map(s=>link(s.organization+' · '+s.title,s.url)).join('')}</div>`:`<div class="sources-line">Original coaching prompt based on the supplied CV. Personalize it using only truthful details.</div>`;}
function heading(eyebrow,title,description,action=''){return `<div class="page-heading"><div><div class="eyebrow"><span class="small-line"></span>${e(eyebrow)}</div><h1>${e(title)}</h1><p>${e(description)}</p></div>${action}</div>`;}
function notice(text,type='',icon='info'){return `<div class="notice ${type}">${I(icon,17)}<p>${e(text)}</p></div>`;}
function render(){
  const active=document.activeElement,focusId=active?.id,selection=active?.selectionStart;
  const focusAttrs=active?.dataset?.action?Object.entries(active.dataset).filter(([k])=>['action','id','day','status','type','rating'].includes(k)):null;
  const navIcons={home:'home',library:'sources',questions:'book',mock:'mic',companies:'company',story:'person',applications:'case',sources:'sources',path:'path'};
  root.innerHTML=`<div class="shell"><button class="mobile-overlay ${ui.menu?'open':''}" data-action="menu" aria-label="Close navigation"></button><aside class="sidebar ${ui.menu?'open':''}" aria-label="Main navigation"><a href="#home" class="brand"><img src="/favicon.svg" alt=""><span class="brand-name">culture<span class="brand-tag">A little more ready, every day</span></span></a><div class="nav-label">YOUR NEXT CHAPTER</div><nav>${Object.entries(paths).map(([key,name],i)=>`<a href="#${key}" class="nav-link ${ui.page===key?'active':''}" ${ui.page===key?'aria-current="page"':''}>${I(navIcons[key],18)}${name}${ui.page===key?'<span class="nav-dot"></span>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="little-note">${I('leaf',17)}<p>Small steps.<br>Remarkable possibilities.</p><small>YOU’RE GROWING, EVEN ON QUIET DAYS.</small></div><div class="profile"><span class="avatar">SB</span><div><strong>Srijita Banerjee</strong><small>Microbiologist in the making</small></div><button data-action="settings" aria-label="Progress and backup settings">${I('settings',16)}</button></div></div></aside><div class="workspace"><header class="topbar"><button class="menu-button" id="mobile-menu-button" data-action="menu" aria-label="Open navigation" aria-expanded="${ui.menu}">${I('menu',21)}</button><div class="breadcrumb"><span class="crumb-root">Your workspace</span><span class="crumb-root">/</span><strong>${e(paths[ui.page])}</strong></div><form class="global-search" id="global-search">${I('search',14)}<input name="query" aria-label="Search all study material" placeholder="Search your study library…" autocomplete="off"></form><span class="private-badge">${I('shield',13)} Your personal prep space</span><button class="top-avatar" data-action="settings" aria-label="Open your progress settings">SB</button></header><main class="main" id="main" tabindex="-1">${!storageAvailable?notice('Browser storage is unavailable. Your changes may not survive a reload. Use Export backup in settings.','warm'):''}${({home:dashboard,library:libraryPage,path:studyPath,questions:questionBank,mock:mockPage,companies:companyPage,story:storyPage,applications:applicationsPage,sources:sourcesPage}[ui.page])()}${footer()}</main></div></div>`;
  const mobile=matchMedia('(max-width:760px)').matches;
  document.querySelector('.sidebar').inert=mobile&&!ui.menu;
  document.querySelector('.workspace').inert=mobile&&ui.menu;
  if(mobile&&ui.menu){document.querySelector('.sidebar').setAttribute('role','dialog');document.querySelector('.sidebar').setAttribute('aria-modal','true');}
  document.title=`${paths[ui.page]} · Culture for Srijita`;
  if(focusId){const el=document.getElementById(focusId);if(el){el.focus({preventScroll:true});if(typeof selection==='number'&&el.setSelectionRange)try{el.setSelectionRange(selection,selection);}catch{}}}
  if(!focusId&&focusAttrs){const selector=focusAttrs.map(([k,v])=>`[data-${k}="${CSS.escape(v)}"]`).join('');root.querySelector(selector)?.focus({preventScroll:true});}
  manageTimer();
}
function footer(){return `<footer class="footer"><span>A little curiosity. A little courage. A whole new chapter.</span><div><button data-action="sources">Sources & research · 30 Oct 2026</button><button data-action="settings">Your data stays on this browser</button><button data-action="egg" data-index="0" aria-label="A little note for you">${I('heart',11)}</button></div></footer>`;}
function microscope(){return `<svg viewBox="0 0 360 280" fill="none" aria-hidden="true"><circle cx="184" cy="137" r="105" fill="#e0e6c8"/><circle cx="184" cy="137" r="90" stroke="#ccd7b4" stroke-dasharray="3 8"/><ellipse cx="186" cy="243" rx="89" ry="12" fill="#d2dabb"/><path d="M230 110c51 38 32 108-18 114h-49" stroke="#5f7c64" stroke-width="22" stroke-linecap="round"/><path d="m162 44 52 25-40 84-52-25z" fill="#405c49"/><path d="m157 38 63 30-8 17-64-31z" fill="#9aaf82"/><path d="m124 127 47 23-8 17-46-22z" fill="#8a9d72"/><path d="m158 35 25-16 47 23-11 22" fill="#6c8868"/><path d="m118 146-14 30 26 13 17-29" fill="#c7c89e"/><path d="M111 190h94" stroke="#4e6c56" stroke-width="9" stroke-linecap="round"/><path d="m155 197-9 31" stroke="#8aa278" stroke-width="12"/><path d="M123 230h116c5 0 9 7 9 12H112c0-5 5-12 11-12Z" fill="#36533f"/><circle cx="231" cy="130" r="19" fill="#36533f"/><circle cx="231" cy="130" r="10" fill="#b8c5a0"/><path d="M271 227c-3-28 8-46 26-57m-22 35c-19-5-24-16-21-29 17 2 24 12 21 29Zm4-10c1-24 12-30 28-28 1 17-10 28-28 28Z" fill="#9cac7c"/><path d="M87 239c0-20-11-41-25-52m20 31c-20-2-27-12-24-26 15 0 24 9 24 26Zm-4-12c2-18 10-26 23-23 0 14-9 22-23 23Z" fill="#b4bd8f"/><circle cx="90" cy="75" r="20" fill="#f3f1d9"/><path d="m82 75 5 5 10-11" stroke="#98aa74" stroke-width="2"/><circle cx="280" cy="91" r="22" fill="#f3eddf"/><g stroke="#bead85" stroke-width="1.5"><ellipse cx="280" cy="91" rx="7" ry="11" transform="rotate(35 280 91)"/><path d="m274 81-3-4m16 7 5-1m-18 16-4 3m14-3 2 5"/></g><path d="m100 143 2 6 6 2-6 2-2 6-2-6-6-2 6-2 2-6Z" fill="#b1ba87"/><circle cx="242" cy="39" r="3" fill="#b1ba87"/><circle cx="70" cy="124" r="3" fill="#c7cdaa"/><path d="m295 139 3 6 6 3-6 3-3 6-3-6-6-3 6-3 3-6Z" fill="#bec79a"/></svg>`;}
function dashboard(){
  const savedCount=D.library.filter(entry=>isLibrarySaved(entry,S)).length;
  const date=new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'short',weekday:'short',timeZone:'Asia/Kolkata'}).format(new Date());
  return `<div class="greeting"><div><h1>Hello, Srijita <span aria-hidden="true">☀</span></h1><p>Your space to learn, remember, and return to. At your own pace.</p></div><span class="date-label">${I('calendar',13)}${e(date)}</span></div>
  <section class="hero" aria-label="Welcome to Culture"><div class="hero-copy"><div class="eyebrow"><span class="small-line"></span> YOUR SCIENCE. YOUR STORY. YOUR OWN PACE.</div><h2>Everything you need.<br>Whenever you need it.</h2><p>A quiet corner for your questions, your notes, and your next opportunity. Start wherever you feel curious.</p>${btn('Open my study library','library','book')}<span class="hero-footnote">Browse. Understand. Come back anytime.</span></div><div class="hero-art">${microscope()}<button class="art-star" data-action="egg" data-index="1" aria-label="A tiny surprise">✧</button><span class="hero-caption">GROW AT YOUR OWN PACE</span></div></section>
  <div class="stats-row">${[[I('book'),D.questions.length,'Practice questions'],[I('save'),savedCount,'Saved for later'],[I('mic'),S.sessions.length,'Mock sessions'],[I('company'),D.companies.length,'Company prep rooms']].map(([icon,value,label])=>`<div class="stat"><span class="stat-icon">${icon}</span><div><strong>${e(value)}</strong><small>${label}</small></div></div>`).join('')}</div>
  <div class="dashboard-grid"><div><div class="section-heading"><h2>Find what you need</h2><a class="text-btn" href="#library">Everything in one place ${I('arrow',13)}</a></div><article class="card library-home-card"><span class="day-badge">YOUR ALWAYS-OPEN STUDY SHELF</span><h3>No schedule. Just a place to begin.</h3><p>Read a topic, revisit a tricky answer, or refresh your project story. Nothing needs to be unlocked or completed first.</p><div class="home-topic-grid">${CATEGORIES.map((category,i)=>`<button type="button" data-action="library-topic" data-topic="${e(category)}"><span>${String(i+1).padStart(2,'0')}</span>${e(category)}${I('arrow',13)}</button>`).join('')}</div><div class="card-footer"><small>Answers, key points, follow-ups, and sources.</small>${btn('Browse the full shelf','library','arrow','small')}</div></article><div class="quick-grid"><button class="quick-card" data-action="library-saved"><span class="quick-icon">${I('save',18)}</span><h3>My revision shelf</h3><p>Everything you bookmarked, ready to revisit.</p><span class="quick-arrow">${I('arrow',13)}</span></button><a class="quick-card" href="#companies"><span class="quick-icon">${I('company',18)}</span><h3>Know the company</h3><p>Reported experiences. Thoughtful prep.</p><span class="quick-arrow">${I('arrow',13)}</span></a><a class="quick-card" href="#story"><span class="quick-icon">${I('person',18)}</span><h3>Own your story</h3><p>Turn your projects into strong answers.</p><span class="quick-arrow">${I('arrow',13)}</span></a></div></div>
  <div class="dashboard-right"><div class="section-heading"><h2>Make it yours</h2><span>${I('spark',15)}</span></div><article class="focus-card"><span class="label">YOUR CURRENT FOCUS</span><h3>Where would you like to grow?</h3><p>Choose a role for your mock interviews. The full study library is always open to you.</p><label for="home-role">Role track</label><select id="home-role" data-change="role">${option(ROLES,S.role)}</select>${btn('Try a mock interview','mock','mic')}</article><article class="card progress-card"><h3>Something worth remembering</h3><p>You can read without a plan, revise without a timer, and practise whenever you want. A little curiosity is enough to start.</p><button class="text-btn" data-action="library-recall">Try a recall card ${I('arrow',13)}</button></article></div></div>
  <div class="quote-strip">${I('leaf',25)}<div><p>You don’t need to know everything to be someone worth hiring.</p><small>BRING YOUR CURIOSITY. THE REST CAN GROW.</small></div><button data-action="breathe" aria-label="Take a calming moment">${I('heart',17)}</button></div>`;
}
function studyPath(){return `${heading('An optional route through the material','Your 14-day study path','Use this only if you want structure. You can also browse and revise everything freely in the study library.',btn('Open the study library','library','book','secondary'))}<div class="data-bar"><p><strong>${S.days.length} of 14 days complete.</strong> Read a few answers, practise aloud, then check off the day when you feel ready. The plan is a guide, not a deadline.</p><progress value="${S.days.length}" max="14" aria-label="Study days completed"></progress></div><div class="path-grid">${D.journey.days.map(d=>`<article id="day-${d.day}" class="card path-card ${S.days.includes(String(d.day))?'complete':''}"><div class="path-top"><span class="day-badge">DAY ${String(d.day).padStart(2,'0')}</span><span class="label">20–30 MIN</span></div><h2>${e(d.title)}</h2><p>${e(d.description)}</p><div class="path-task"><strong>Your small mission</strong><br>${e(d.task)}</div><div class="path-actions"><button class="checkbox-btn" data-action="complete-day" data-day="${d.day}" aria-pressed="${S.days.includes(String(d.day))}"><span class="check-box">${S.days.includes(String(d.day))?I('check',12):''}</span>${S.days.includes(String(d.day))?'Day complete':'Mark complete'}</button><button class="text-btn" data-action="day-study" data-day="${d.day}">Open practice ${I('arrow',13)}</button></div></article>`).join('')}</div>`;}
function questionBank(){
  const list=filterQuestions(D.questions,{...ui,reviewed:S.reviewed,saved:S.saved}),pages=Math.max(1,Math.ceil(list.length/10));ui.pageNumber=Math.min(ui.pageNumber,pages);
  return `${heading('Understand it. Say it. Make it yours.','The question bank','Brief, source-linked answers with key points, common traps, and a follow-up to stretch your thinking.',btn('Print this page','print','print','secondary'))}<div class="filters"><div class="search-field">${I('search',15)}<input id="question-search" data-input="question-search" aria-label="Search questions" placeholder="Search a concept, method, or question…" value="${e(ui.search)}"></div><select id="filter-category" data-filter="category" aria-label="Filter by topic">${option(['All topics',...CATEGORIES],ui.category)}</select><select id="filter-difficulty" data-filter="difficulty" aria-label="Filter by difficulty">${option(['All levels','Basic','Intermediate','Advanced'],ui.difficulty)}</select><select id="filter-role" data-filter="role" aria-label="Filter by role">${option(['All roles',...ROLES],ui.role)}</select></div><div class="filter-tabs" aria-label="Question status">${['All questions','To review','Saved','Reviewed'].map(status=>`<button class="tab ${ui.status===status?'active':''}" data-action="question-status" data-status="${status}" aria-pressed="${ui.status===status}">${status}${status==='Saved'?` (${S.saved.length})`:''}</button>`).join('')}<button class="text-btn" data-action="clear-filters">Clear filters</button><span class="results-label">${list.length} questions · ${S.reviewed.length} reviewed</span></div><div class="question-list">${list.slice((ui.pageNumber-1)*10,ui.pageNumber*10).map((q,i)=>questionCard(q,(ui.pageNumber-1)*10+i+1)).join('')||`<div class="empty">${I('search',28)}<h3>A fresh place to look</h3><p>No questions match these filters. Try a broader topic or clear your search.</p>${btn('Clear filters','clear-filters','arrow','secondary')}</div>`}</div>${list.length?`<div class="pagination">${btn('Previous','previous-page','left','secondary small',ui.pageNumber===1?'disabled':'')}<span>Page ${ui.pageNumber} of ${pages}</span>${btn('Next','next-page','arrow','secondary small',ui.pageNumber===pages?'disabled':'')}</div>`:''}<div class="notice">${I('shield',17)}<p>These are educational interview answers, not validated laboratory procedures. For real work, follow the current approved method, site SOP, and applicable standard. Difficulty and study order are editorial choices.</p></div>`;
}
function questionCard(q,index){const open=ui.printAll||ui.openQuestion===q.id;return `<article class="question-card ${S.reviewed.includes(q.id)?'reviewed':''}" id="${q.id}"><div class="question-title"><span class="question-number">${String(index).padStart(2,'0')}</span><button class="question-toggle" id="toggle-${q.id}" data-action="toggle-question" data-id="${q.id}" aria-expanded="${open}" aria-controls="answer-${q.id}"><h2>${e(q.title)}</h2><span class="question-meta">${pill(q.difficulty,q.difficulty)}<span>${e(q.category)}</span>${S.reviewed.includes(q.id)?`<span>· ${I('check',10)} Reviewed</span>`:''}</span></button><button class="icon-btn ${S.saved.includes(q.id)?'selected':''}" data-action="save-question" data-id="${q.id}" aria-label="${S.saved.includes(q.id)?'Unsave':'Save'} question" aria-pressed="${S.saved.includes(q.id)}">${I('save',18)}</button><span class="chevron">${I(open?'down':'chevron',16)}</span></div>${open?`<div class="question-body" id="answer-${q.id}"><p>${e(q.answer)}</p><div class="key-points"><strong>Hit these key points</strong><ul>${q.keyPoints.map(p=>`<li>${e(p)}</li>`).join('')}</ul></div><div class="pitfall"><strong>A common trap:</strong> ${e(q.pitfall)}</div><div class="follow-up"><strong>Be ready for:</strong> ${e(q.followUp)}</div>${sourceLinks(q.sourceIds)}<div class="answer-actions">${btn(S.reviewed.includes(q.id)?'Reviewed — undo':'I’ve reviewed this','review-question','check',S.reviewed.includes(q.id)?'soft':'',`data-id="${q.id}"`)}<small>Try saying it in your own words first.</small></div></div>`:''}</article>`;}
function companyPage(){
  if(ui.company)return companyDetail(D.companies.find(c=>c.id===ui.company));
  const companies=D.companies.filter(c=>[c.name,c.sector,...c.roles].join(' ').toLowerCase().includes(ui.companySearch.toLowerCase()));
  return `${heading('A little context goes a long way','The company room','Explore the work, read candid interview accounts, and prepare with questions that fit the role.')} ${notice('Reported experiences are individual accounts, not verified hiring policy. Geography, date, and seniority matter. Suggested practice is written for this guide and is never presented as a question a company asked.','warm')}<div class="filters"><div class="search-field">${I('search',15)}<input id="company-search" data-input="company-search" placeholder="Find a company or role…" aria-label="Search companies" value="${e(ui.companySearch)}"></div></div><div class="company-grid">${companies.map(c=>`<article class="card company-card"><div class="company-top"><span class="company-logo">${e(c.initials)}</span><div><h2>${e(c.name)}</h2><small>${e(c.sector)}</small></div></div><p>${e(c.overview)}</p><div class="company-tags">${c.roles.map(r=>pill(r)).join('')}</div><div class="card-footer"><span class="report-count">${I('person',13)}${c.reports.length?`${c.reports.length} reported ${c.reports.length===1?'experience':'experiences'}`:'Role preparation available'}</span><a class="text-btn" href="#companies/${c.id}">Step inside ${I('arrow',14)}</a></div></article>`).join('')||'<div class="empty"><h3>No matching companies</h3><p>Try a company name or a broader role.</p></div>'}</div>`;
}
function companyDetail(c){return `<a class="back-link" href="#companies">${I('left',14)} Back to the company room</a><div class="company-detail-header"><span class="company-logo">${e(c.initials)}</span><div><div class="eyebrow">${e(c.sector)}</div><h1>${e(c.name)}</h1><p>${e(c.locationNote)}</p></div></div><div class="two-col"><div class="stack"><section><div class="section-heading"><h2>What candidates reported</h2><small>${c.reports.length} public accounts</small></div>${c.reports.length?c.reports.map(r=>`<article class="card report-card"><span class="pill">COMMUNITY ACCOUNT · ANECDOTAL</span><h3>${e(r.title)}</h3><div class="report-meta">${e(r.platform)} · ${e(r.date)} · ${e(r.role)}</div><p>${e(r.summary)}</p><div class="topic-chips">${r.reportedTopics.map(t=>pill(t)).join('')}</div>${r.questions?.length?`<div class="mini-label">Reported topic · practice prompt and suggested answer</div>${r.questions.map(q=>`<details class="practice-item"><summary>${e(q.question)}</summary><p>${e(q.answer)}</p></details>`).join('')}`:''}<p class="caveat">${e(r.caveat)}</p>${link('Read the original account',r.url)}</article>`).join(''):notice('No accessible, role-specific interview account was verified for this company. Use the official role information and suggested practice below.','warm')}${notice(c.evidenceNote,'warm')}</section><section class="card"><h3>My interview notes</h3><p class="report-meta">If you interview here, save the actual questions and context while they are fresh. These are your private notes on this browser.</p><label for="company-note-${c.id}">Role, date, questions, and one learning point</label><textarea id="company-note-${c.id}" class="notepad" data-note="company-${c.id}" placeholder="My own interview experience…">${e(S.notes['company-'+c.id]||'')}</textarea></section><section class="card"><div class="eyebrow">SUGGESTED ROLE PREPARATION</div><h2>Questions to rehearse</h2><p class="report-meta">${e(c.practiceLabel||'Author-written practice, not evidence that this company asked these questions.')}</p>${(c.practiceQuestions||[]).map(q=>`<details class="practice-item"><summary>${e(q.question)}</summary><p>${e(q.answer)}</p></details>`).join('')}<div class="sources-line">${(c.practiceSourceUrls||[]).map((url,i)=>link(`Reference ${i+1}`,url)).join('')}</div></section></div><aside class="stack"><section class="card role-guide"><span class="label">START WITH THE ROLE</span><h3>${e(c.name)} at a glance</h3><p>${e(c.overview)}</p><div class="mini-label">Relevant role families</div><div class="topic-chips">${c.roles.map(r=>pill(r)).join('')}</div><div class="mini-label">Prepare these topics</div><ul>${c.practiceTopics.map(t=>`<li>${e(t)}</li>`).join('')}</ul>${link('Official company careers / role page',c.officialUrl)}<p class="report-meta">This is a preparation directory, not a live vacancy feed. Check eligibility, location, and opening status on the official site.</p></section><section class="focus-card"><span class="label">MAKE THE CONVERSATION COUNT</span><h3>Ask something thoughtful.</h3><p>“How are new team members trained and signed off for routine work?”</p><p>“What would good progress look like in the first three months?”</p>${btn('Practise my introduction','story','arrow','secondary')}</section></aside></div>`;}
function storyPage(){return `${heading('You already have a story worth telling','Let your experience speak','Use your real projects to show careful thinking, curiosity, and the confidence to keep learning.')}<div class="story-intro"><section class="pitch-card"><span class="label">YOUR 60–90 SECOND INTRODUCTION</span><h2>${e(D.journey.intro.headline)}</h2><p>${e(D.journey.intro.pitch)}</p><small>${e(D.journey.intro.closer)}</small></section><div class="credentials">${[['88%','M.Sc. Microbiology','Sister Nivedita University · 2026'],['83%','B.Sc. Microbiology','SVIMS · 2024'],['BITM','Biotech Lab','Research internship'],['AIIHPH','Food-safety exposure','Research internship']].map(([value,title,desc])=>`<div class="credential"><strong>${e(value)}</strong><p><b>${e(title)}</b><br>${e(desc)}</p></div>`).join('')}</div></div>${notice('Personalized from the supplied CV. These drafts are rehearsal prompts: verify your methods and findings in your own records. Replace prompts with your own details before using an answer.','warm')}<div class="section-heading"><h2>Your projects, in your words</h2><small>Aim → contribution → evidence → learning</small></div><div class="project-grid">${D.journey.projects.map(p=>`<article class="card project-card"><span class="label">${e(p.tag)}</span><h3>${e(p.title)}</h3><p>${e(p.summary)}</p><details><summary>Build my project answer</summary><p>${e(p.answer)}</p></details>${p.followUps.map(f=>`<details><summary>${e(f.question)}</summary><p>${e(f.answer)}</p></details>`).join('')}<div class="honesty">${e(p.honestyNote)}</div><label for="note-${p.id}" class="mini-label">MY VERIFIED DETAILS · SAVED ON THIS BROWSER</label><textarea class="notepad" id="note-${p.id}" data-note="${p.id}" placeholder="My exact method, my contribution, one real finding, one lesson…">${e(S.notes[p.id]||'')}</textarea></article>`).join('')}</div><div class="section-heading"><h2>The human side of the interview</h2><span class="label">HONEST ANSWERS > PERFECT SCRIPTS</span></div><div class="hr-list">${D.journey.hr.map(h=>`<details class="card hr-item"><summary>${e(h.question)}</summary><p>${e(h.answer)}</p><p class="tip">${e(h.tip)}</p></details>`).join('')}</div>`;}
function mockPage(){
  if(mock?.complete)return mockSummary(mock);
  if(mock)return activeMock();
  return `${heading('A safe place to find your voice','Your practice interview','Think out loud, compare your answer, and choose what to revisit. Progress comes from practising.')}<div class="mock-setup"><div class="mock-intro"><div class="mock-icon">${I('mic',29)}</div><h2>A rehearsal, with room to grow.</h2><p>Speak your answer aloud or jot it down. Reveal the guide, check the key points, and rate your answer honestly. No recording, no AI score.</p></div><form id="mock-setup" class="card"><div class="form-grid"><div><label for="mock-role">Role to prepare for</label><select id="mock-role" name="role">${option(ROLES,S.role)}</select></div><div><label for="mock-level">Question level</label><select id="mock-level" name="level">${option(['Mixed levels','Basic','Intermediate','Advanced'],'Mixed levels')}</select></div><div><label for="mock-count">Session length</label><select id="mock-count" name="count"><option value="5">5 questions · a small step</option><option value="10">10 questions · a deeper practice</option></select></div><div><label for="mock-time">Gentle timer per question</label><select id="mock-time" name="time"><option value="90">90 seconds</option><option value="60">60 seconds</option><option value="0">No timer · my own pace</option></select></div></div><div class="mock-rubric"><div><strong>1. Answer</strong><p>Use a definition, the key idea, and a relevant example.</p></div><div><strong>2. Compare</strong><p>Read the guide. Notice what you covered and what you missed.</p></div><div><strong>3. Reflect</strong><p>Choose “revisit”, “getting there”, or “clear & complete”.</p></div></div><button class="btn" type="submit">Start my practice ${I('arrow',15)}</button></form>${sessionHistory()}</div>`;
}
function activeMock(){const q=D.questions.find(x=>x.id===mock.ids[mock.index]);if(!q){mock=null;persistMock();return mockPage();}return `<div class="mock-session">${heading('Your voice gets stronger with practice','You have this, Srijita.','A thoughtful pause is allowed. A breath is allowed. Learning is the whole point.')}<div class="mock-top"><span class="day-badge">QUESTION ${mock.index+1} OF ${mock.ids.length}</span><small>${e(mock.role)} · ${e(q.difficulty)}</small><span class="timer ${mock.remaining===0&&mock.time?'expired':''}" id="timer-display">${I('clock',14)}<span id="timer-text">${timerText()}</span></span><button class="text-btn" data-action="pause-mock">${I(mock.paused?'play':'pause',13)}${mock.paused?'Resume':'Pause'}</button><button class="text-btn" data-action="exit-mock">End session</button></div><progress value="${mock.index}" max="${mock.ids.length}" aria-label="Questions answered"></progress><article class="card mock-question"><span class="label">${e(q.category)}</span><h2>${e(q.title)}</h2><label for="mock-answer">Your thoughts · optional, saved on this browser</label><textarea id="mock-answer" class="mock-answer" data-input="mock-answer" placeholder="Take a breath. Start with what you know…" ${mock.paused?'disabled':''}>${e(mock.draft||'')}</textarea>${mock.paused?notice('Practice is paused. Take your time. Resume when you feel ready.','purple'):mock.revealed?'':btn('Show the answer guide','reveal-mock','book','secondary')}${mock.revealed?`<div class="mock-reference"><div class="eyebrow">AN ANSWER TO LEARN FROM</div><p>${e(q.answer)}</p><div class="key-points"><strong>Check your answer against these points</strong><ul>${q.keyPoints.map(k=>`<li>${e(k)}</li>`).join('')}</ul></div><div class="pitfall">${e(q.pitfall)}</div><p class="follow-up"><strong>Follow-up:</strong> ${e(q.followUp)}</p>${sourceLinks(q.sourceIds)}<div class="mini-label">HOW DID IT FEEL? · YOUR OWN ASSESSMENT</div><div class="rating-row">${[['revisit','I need to revisit this'],['partial','I’m getting there'],['strong','Clear & complete']].map(([rating,text])=>`<button class="rating-btn" data-action="rate-mock" data-rating="${rating}" ${mock.paused?'disabled':''}>${text} ${I('arrow',12)}</button>`).join('')}</div></div>`:''}</article><button class="text-btn" data-action="breathe">${I('leaf',15)} A moment to breathe</button></div>`;}
function timerText(){return mock.time?mock.remaining?`${Math.floor(mock.remaining/60)}:${String(mock.remaining%60).padStart(2,'0')}${mock.paused?' · paused':''}`:'Time’s up — keep going at your pace':'At your pace';}
function persistMock(){try{if(mock)localStorage.setItem(STORAGE_KEY+'.mock',JSON.stringify(mock));else localStorage.removeItem(STORAGE_KEY+'.mock');}catch{}}
function manageTimer(){clearInterval(timer);if(ui.page!=='mock'||!mock||mock.complete||mock.paused||mock.revealed||!mock.time||mock.remaining<=0)return;timer=setInterval(()=>{mock.remaining=Math.max(0,mock.remaining-1);persistMock();const t=document.querySelector('#timer-text');if(t)t.textContent=timerText();if(mock.remaining===0){clearInterval(timer);document.querySelector('#timer-display')?.classList.add('expired');}},1000);}
function finishMock(){mock.complete=true;mock.finishedAt=new Date().toISOString();const session={id:mock.id,role:mock.role,date:mock.finishedAt,answers:mock.answers};S.sessions=[...S.sessions.filter(s=>s.id!==session.id),session].slice(-30);persist();persistMock();render();window.scrollTo(0,0);}
function mockSummary(session){const answers=session.answers,counts={revisit:0,partial:0,strong:0};answers.forEach(a=>{if(a.rating in counts)counts[a.rating]++;});return `<div class="mock-session">${heading('You showed up. That counts.','A little more confident.','This is your reflection on the session, not an objective score or a prediction of hiring outcomes.')}<div class="stats-row">${[['check',answers.length,'Questions practised'],['book',counts.revisit,'To revisit'],['leaf',counts.partial,'Getting there'],['spark',counts.strong,'Clear & complete']].map(([icon,n,text])=>`<div class="stat"><span class="stat-icon">${I(icon)}</span><div><strong>${n}</strong><small>${text}</small></div></div>`).join('')}</div><div class="stack">${answers.map(a=>{const q=D.questions.find(q=>q.id===a.id);if(!q)return '';return `<details class="card"><summary>${e(q.title)} ${pill({revisit:'Revisit',partial:'Getting there',strong:'Clear & complete'}[a.rating]||'Reviewed')}</summary><p><strong>Your answer:</strong> ${e(a.text||'Answered aloud — no written notes.')}</p><p><strong>Answer guide:</strong> ${e(q.answer)}</p>${sourceLinks(q.sourceIds)}<button class="text-btn" data-action="save-question" data-id="${q.id}">${I('save',13)}${S.saved.includes(q.id)?'Saved — remove':'Save for later'}</button></details>`;}).join('')}</div><div class="answer-actions">${btn('Practise again','new-mock','arrow')}${btn('Review the question bank','questions','book','secondary')}</div></div>`;}
function sessionHistory(){return `<div class="section-heading"><h2>Your recent practice</h2><small>Last 30 completed sessions</small></div><div class="card">${S.sessions.length?S.sessions.slice(-5).reverse().map(s=>`<div class="session-row"><span class="stat-icon">${I('mic',16)}</span><div><strong>${e(s.role)}</strong><small>${e(new Date(s.date).toLocaleDateString('en-IN'))} · ${s.answers.length} questions</small></div><button class="text-btn" data-action="view-session" data-id="${e(s.id)}">Reflect ${I('arrow',12)}</button></div>`).join(''):'<p class="report-meta">Your completed sessions will live here. Your first one is a good place to start.</p>'}</div>`;}
function applicationsPage(){const apps=S.applications;return `${heading('Make room for the opportunity','Your next-step tracker','Keep a small, steady rhythm: find a suitable role, tailor your application, and plan the next step.',btn('Add an opportunity','add-application','plus'))}<div class="tracker-head">${[[apps.length,'Opportunities'],[apps.filter(a=>a.status==='Applied').length,'Applications'],[apps.filter(a=>a.status==='Interview').length,'Interviews'],[apps.filter(a=>a.status==='Offer').length,'Offers']].map(([n,label])=>`<div class="tracker-stat"><strong>${n}</strong><small>${label}</small></div>`).join('')}</div>${notice('Entries are stored only in this browser. Nothing is submitted to employers. Save a backup to carry your progress to another device.')}<div>${apps.map(a=>`<article class="card application"><div><h3>${e(a.company)}</h3><p>${e(a.role)}</p><small class="report-meta">${a.date?e(a.date):'No next date set'}</small></div><select data-app-status="${e(a.id)}" aria-label="Status for ${e(a.company)}">${option(['Wishlist','Applied','Interview','Offer','Closed'],a.status)}</select><div class="next-action"><small>Next small step</small>${e(a.next||'Add a next step to keep moving.')}${safeUrl(a.url)?`<br>${link('Job link',a.url)}`:''}</div><div class="app-controls"><button class="icon-btn" data-action="edit-application" data-id="${e(a.id)}" aria-label="Edit ${e(a.company)}">${I('edit',16)}</button><button class="icon-btn" data-action="delete-application" data-id="${e(a.id)}" aria-label="Delete ${e(a.company)}">${I('trash',16)}</button></div></article>`).join('')||`<div class="empty">${I('case',32)}<h3>Your next chapter has a starting point.</h3><p>Add a role you’re curious about. You don’t need a long list — just one thoughtful next step.</p>${btn('Add my first opportunity','add-application','plus')}</div>`}</div><div class="section-heading"><h2>Find roles that fit your starting point</h2><small>Read the eligibility, not just the job title.</small></div><div class="company-grid">${D.journey.roleGuides.map(r=>`<article class="card role-guide"><h3>${e(r.name)}</h3><p>${e(r.description)}</p><div class="mini-label">Search terms to try</div><div class="topic-chips">${r.searchTerms.map(t=>pill(t)).join('')}</div><ul>${r.focus.map(t=>`<li>${e(t)}</li>`).join('')}</ul><div class="honesty">${e(r.gap)}</div><p class="report-meta"><strong>Your first move:</strong> ${e(r.firstWeekTask)}</p></article>`).join('')}</div>`;}
function sourcesPage(){const sources=D.allSources.filter(s=>ui.sourceType==='All sources'||ui.sourceType==='Technical & learning'&&['Primary guidance','Textbook'].includes(s.type)||ui.sourceType==='Company careers'&&s.type==='Company careers'||ui.sourceType==='Community reports'&&s.type==='Community report');return `${heading('Good preparation deserves good evidence','The source library','Primary references for science. Official pages for role context. Clearly labeled community accounts for perspective.')}<div class="two-col"><section class="card"><h3>How this guide was put together</h3><ul class="overview-list"><li>Reviewed on 30 October 2026. Every technical question links to its supporting reference.</li><li>Answers are concise teaching summaries. Standards, limits, and approved methods depend on the work and location.</li><li>Company accounts are individual reports. We don’t turn them into hiring statistics or claim they predict your interview.</li><li>Your profile comes from the supplied CV. Missing project results are left for you to verify.</li><li>No invented success rates, salary promises, or “most asked” rankings. The study order and difficulty labels are editorial.</li></ul></section><section class="focus-card"><span class="label">A NOTE ON CURRENCY</span><h3>Learn the idea. Check the version.</h3><p>For AST, check current organism–drug breakpoints. For clinical research, distinguish E6(R2) training from E6(R3). For regulated work, check the applicable local rules and site procedures.</p><p>External links may change after review. A source link is evidence to explore, not an endorsement of every claim on its site.</p></section></div><div class="filter-tabs">${['All sources','Technical & learning','Company careers','Community reports'].map(t=>`<button class="tab ${ui.sourceType===t?'active':''}" data-action="source-type" data-type="${t}" aria-pressed="${ui.sourceType===t}">${t}</button>`).join('')}<span class="results-label">${sources.length} references</span></div><div class="source-grid">${sources.map(s=>`<article class="card source-card"><span class="source-type">${e(s.type)} · ${e(s.organization)}</span><h3>${e(s.title)}</h3><p>${e(s.note)}</p>${link('Open original source',s.url)}</article>`).join('')}</div>`;}

function openModal(title,body){if(!modal.open)modalReturnFocus=document.activeElement;modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">${e(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${I('close',20)}</button></div><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();}
function closeModal(){modal.close();modalReturnFocus?.focus?.();}
function egg(index){const note=D.journey.notes[index%D.journey.notes.length];openModal('A little something for you',`<div class="egg"><span class="egg-flower" aria-hidden="true">✿</span><h3>${e(note.title)}</h3><p>${e(note.text)}</p><small>Always in your corner.<br>With love, from me to you.</small></div><div class="modal-actions">${btn('Keep growing','close-modal','heart','soft')}</div>`);}
function settings(){openModal('Your little workspace',`<p>Your reviewed questions, notes, applications, and practice sessions stay in this browser. No account, analytics, or remote database. Clearing browser data removes them. Use a backup to move between your phone and laptop. Backups include completed mock sessions; an unfinished mock stays on its current browser.</p><div class="data-bar"><p><strong>${S.reviewed.length} reviewed answers · ${S.days.length} completed days · ${S.applications.length} opportunities</strong><br>Keep a copy whenever you’ve made progress.</p></div><div class="answer-actions">${btn('Export backup','export','download')}${btn('Import backup','import','upload','secondary')}</div><input id="import-file" type="file" accept=".json,application/json" hidden><div class="honesty">A downloaded backup includes the personal notes and application details you added. Keep it somewhere you trust. Import replaces this browser’s saved progress.</div><div class="modal-actions">${btn('Reset local progress','confirm-reset','trash','secondary small')}${btn('Done','close-modal','check','small')}</div>`);}
function checklist(){openModal('A calm start to interview day',`<p>Light revision, practical preparation, and a little room to breathe. You can return to this checklist from the study path.</p><ul class="checklist">${D.journey.checklist.map(c=>`<li><button id="check-${c.id}" class="checkbox-btn ${S.checklist.includes(c.id)?'checked':''}" data-action="check-item" data-id="${c.id}" aria-pressed="${S.checklist.includes(c.id)}"><span class="check-box">${S.checklist.includes(c.id)?I('check',12):''}</span>${e(c.text)}</button></li>`).join('')}</ul><div class="modal-actions">${btn('A moment to breathe','breathe','leaf','secondary')}${btn('I’m ready for my next step','close-modal','check')}</div>`);}
function applicationForm(id){const a=S.applications.find(a=>a.id===id)||{id:'',company:'',role:'',status:'Wishlist',date:'',next:'',url:''};openModal(a.id?'Edit your opportunity':'One thoughtful next step',`<form id="application-form" data-id="${e(a.id)}"><div class="form-grid"><div><label for="app-company">Company *</label><input id="app-company" name="company" required maxlength="150" value="${e(a.company)}" placeholder="Company name"></div><div><label for="app-role">Role *</label><input id="app-role" name="role" required maxlength="150" value="${e(a.role)}" placeholder="e.g. Microbiology trainee"></div><div><label for="app-status">Where things stand</label><select id="app-status" name="status">${option(['Wishlist','Applied','Interview','Offer','Closed'],a.status)}</select></div><div><label for="app-date">Next action / interview date</label><input id="app-date" name="date" type="date" value="${e(a.date)}"></div><div class="full"><label for="app-url">Job or company URL · optional</label><input id="app-url" name="url" type="url" maxlength="2000" value="${e(a.url)}" placeholder="https://…"></div><div class="full"><label for="app-next">Your next small step</label><textarea id="app-next" name="next" maxlength="1000" placeholder="Tailor my CV, follow up on Friday, prepare my project story…">${e(a.next)}</textarea></div></div><p class="error-text" id="application-error" role="alert"></p><div class="modal-actions">${btn('Cancel','close-modal','close','secondary')}<button type="submit" class="btn">Save opportunity ${I('check',15)}</button></div></form>`);}
function confirmDelete(id){const a=S.applications.find(a=>a.id===id);if(!a)return;openModal('Remove this opportunity?',`<p>Remove ${e(a.company)} — ${e(a.role)} from this browser’s tracker?</p><div class="modal-actions">${btn('Keep it','close-modal','left','secondary')}${btn('Remove opportunity','remove-application','trash','danger',`data-id="${e(id)}"`)}</div>`);}
function dayStudy(day){const d=D.journey.days.find(d=>String(d.day)===String(day));if(!d)return;if(d.day===7)return navigate('mock');if(d.day===8){ui.category='All topics';ui.search='';ui.role=S.role;ui.status='All questions';ui.difficulty='All levels';ui.pageNumber=1;return navigate('questions');}if(d.day===10&&S.role==='Research'){ui.category='Lab methods';ui.search='';ui.role='Research';ui.status='All questions';ui.difficulty='All levels';ui.pageNumber=1;return navigate('questions');}if(d.category==='Company research')return navigate('companies');if(d.category==='Mock interview')return navigate('mock');if(d.category==='Interview day')return checklist();if(d.category==='My story'||d.category==='Resume & projects')return navigate('story');ui.category=CATEGORIES.includes(d.category)?d.category:'All topics';ui.difficulty='All levels';ui.search='';ui.role='All roles';ui.status='All questions';ui.pageNumber=1;ui.openQuestion=d.questionIds?.[0]||null;navigate('questions');}
document.addEventListener('click',event=>{
  if(event.target.closest('.skip-link')){event.preventDefault();document.querySelector('#main')?.focus();return;}
  const b=event.target.closest('[data-action]');if(!b||b.disabled)return;
  const {action,id,day}=b.dataset;
  if(paths[action]){if(modal.open)closeModal();return navigate(action);}
  switch(action){
    case 'library-clear':resetLibrary();render();break;
    case 'library-topic':resetLibrary();ui.libraryTopic=b.dataset.topic;ui.libraryKind='Questions & answers';navigate('library');break;
    case 'library-saved':resetLibrary();ui.libraryKind='Saved for later';navigate('library');break;
    case 'library-recall':resetLibrary();ui.libraryMode='recall';ui.libraryKind='Questions & answers';navigate('library');break;
    case 'library-mode':ui.libraryMode=b.dataset.mode;ui.recallIndex=0;ui.recallRevealed=false;if(ui.libraryMode==='recall'){if(!['Questions & answers','Saved for later'].includes(ui.libraryKind))ui.libraryKind='Questions & answers';if(!['All topics',...CATEGORIES].includes(ui.libraryTopic))ui.libraryTopic='All topics';}render();break;
    case 'library-save':{const entry=D.library.find(entry=>entry.id===id);if(entry){toggleArray(entry.questionId?'saved':'librarySaved',entry.questionId||entry.id);render();}break;}
    case 'library-top':document.getElementById('library-search')?.scrollIntoView({block:'center'});document.getElementById('library-search')?.focus({preventScroll:true});break;
    case 'library-jump':{const target=document.getElementById(shelfId(b.dataset.topic));target?.scrollIntoView({block:'start'});target?.focus({preventScroll:true});break;}
    case 'library-reveal':ui.recallRevealed=true;render();break;
    case 'library-hide':ui.recallRevealed=false;render();break;
    case 'library-previous':ui.recallIndex=Math.max(0,ui.recallIndex-1);ui.recallRevealed=false;render();document.querySelector('.library-recall')?.scrollIntoView({block:'start'});break;
    case 'library-next':{const count=librarySelection().filter(entry=>entry.questionId).length;ui.recallIndex=count?(ui.recallIndex+1)%count:0;ui.recallRevealed=false;render();document.querySelector('.library-recall')?.scrollIntoView({block:'start'});break;}
    case 'library-print':{const oldMode=ui.libraryMode;ui.libraryPrint=true;ui.libraryMode='read';render();window.print();ui.libraryPrint=false;ui.libraryMode=oldMode;render();break;}
    case 'menu':ui.menu=!ui.menu;render();if(ui.menu)document.querySelector('.sidebar .nav-link.active')?.focus();else document.querySelector('.menu-button')?.focus();break;
    case 'toggle-question':ui.openQuestion=ui.openQuestion===id?null:id;render();break;
    case 'save-question':toggleArray('saved',id);if(modal.open)toast(S.saved.includes(id)?'Saved for a quieter moment.':'Removed from saved questions.');else render();break;
    case 'review-question':toggleArray('reviewed',id);render();toast(S.reviewed.includes(id)?'One more small step. Nicely done.':'Marked for another look.');break;
    case 'question-status':ui.status=b.dataset.status;ui.pageNumber=1;render();break;
    case 'clear-filters':Object.assign(ui,{search:'',category:'All topics',difficulty:'All levels',role:'All roles',status:'All questions',pageNumber:1});render();break;
    case 'previous-page':ui.pageNumber--;ui.openQuestion=null;render();document.querySelector('.filters')?.scrollIntoView();break;
    case 'next-page':ui.pageNumber++;ui.openQuestion=null;render();document.querySelector('.filters')?.scrollIntoView();break;
    case 'quick-question':Object.assign(ui,{search:'',category:'All topics',role:'All roles',difficulty:'All levels',status:'All questions',pageNumber:Math.floor(D.questions.findIndex(q=>q.id===id)/10)+1,openQuestion:id});navigate('questions');setTimeout(()=>document.getElementById(id)?.scrollIntoView({block:'start'}),30);break;
    case 'complete-day':toggleArray('days',String(day));render();toast(S.days.includes(String(day))?'A day of growing. You can be proud of that.':'You can come back to this day anytime.');break;
    case 'day-study':dayStudy(day);break;
    case 'day-open':navigate('path');setTimeout(()=>document.querySelector(`#day-${day}`)?.scrollIntoView({block:'center'}),40);break;
    case 'settings':settings();break;
    case 'close-modal':closeModal();break;
    case 'egg':egg(Number(b.dataset.index||0));break;
    case 'breathe':if(mock&&!mock.complete){mock.paused=true;persistMock();manageTimer();if(ui.page==='mock')render();}openModal('A moment, just for you',`<div class="breathing-copy"><div class="breathing-orb" aria-hidden="true"></div><h3>There is time for a breath.</h3><p>If it feels comfortable, breathe in as the circle grows,<br>and out as it softens. Or simply sit for a moment.</p><p>You don’t have to earn your place here.</p></div><div class="modal-actions">${btn('Back at my own pace','close-modal','leaf')}</div>`);break;
    case 'checklist':checklist();break;
    case 'check-item':toggleArray('checklist',id);checklist();document.getElementById(`check-${id}`)?.focus();break;
    case 'source-type':ui.sourceType=b.dataset.type;render();break;
    case 'print':ui.printAll=true;render();window.print();ui.printAll=false;render();break;
    case 'add-application':applicationForm();break;
    case 'edit-application':applicationForm(id);break;
    case 'delete-application':confirmDelete(id);break;
    case 'remove-application':S.applications=S.applications.filter(a=>a.id!==id);persist();closeModal();render();toast('Opportunity removed.');break;
    case 'reveal-mock':mock.revealed=true;persistMock();render();break;
    case 'pause-mock':mock.paused=!mock.paused;persistMock();render();break;
    case 'exit-mock':mock.paused=true;persistMock();render();openModal('Pause here or finish?',`<p>Your current practice is saved on this browser. You can return to it later, or end it and keep the questions you’ve already rated.</p><div class="modal-actions">${btn('Keep practising','resume-mock','left','secondary')}${btn('End & save reflection','finish-mock','check')}</div>`);mock.paused=true;persistMock();manageTimer();break;
    case 'resume-mock':closeModal();if(mock){mock.paused=false;persistMock();render();}break;
    case 'finish-mock':closeModal();finishMock();break;
    case 'rate-mock':{const qid=mock.ids[mock.index];mock.answers.push({id:qid,text:mock.draft||'',rating:b.dataset.rating});if(!S.reviewed.includes(qid))S.reviewed.push(qid);if(b.dataset.rating==='revisit'&&!S.saved.includes(qid))S.saved.push(qid);persist();mock.index++;if(mock.index>=mock.ids.length)finishMock();else{mock.remaining=mock.time;mock.draft='';mock.revealed=false;persistMock();render();window.scrollTo(0,0);}break;}
    case 'new-mock':if(modal.open)closeModal();mock=null;persistMock();render();window.scrollTo(0,0);break;
    case 'view-session':{const session=S.sessions.find(s=>s.id===id);if(session){openModal('Your practice reflection',mockSummary(session));}break;}
    case 'export':{const blob=new Blob([JSON.stringify({app:'culture',exportedAt:new Date().toISOString(),...S},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`culture-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your backup is ready. Keep it somewhere safe.');break;}
    case 'import':document.querySelector('#import-file')?.click();break;
    case 'confirm-reset':openModal('Start with a clean page?',`<p>This clears this browser’s reviewed answers, saved questions, study days, notes, mock sessions, and job tracker. Export a backup first if you want to keep them.</p><div class="modal-actions">${btn('Keep my progress','close-modal','left','secondary')}${btn('Clear local progress','reset','trash','danger')}</div>`);break;
    case 'reset':S=structuredClone(DEFAULT_STATE);mock=null;persistMock();persist();closeModal();render();toast('A fresh start, at your pace.');break;
    case 'accept-import':if(window.pendingCultureImport){S=sanitizeProgress(window.pendingCultureImport);delete window.pendingCultureImport;mock=null;persistMock();persist();closeModal();render();toast('Your progress is back. Welcome home.');}break;
  }
});
let searchDelay;
document.addEventListener('input',event=>{
  const el=event.target;
  if(el.dataset.note){S.notes[el.dataset.note]=el.value;persist();}
  if(el.dataset.input==='mock-answer'&&mock){mock.draft=el.value;persistMock();}
  if(el.dataset.input==='library-search'){ui.librarySearch=el.value;ui.recallIndex=0;ui.recallRevealed=false;clearTimeout(searchDelay);searchDelay=setTimeout(render,180);}
  if(el.dataset.input==='question-search'){ui.search=el.value;ui.pageNumber=1;clearTimeout(searchDelay);searchDelay=setTimeout(render,180);}
  if(el.dataset.input==='company-search'){ui.companySearch=el.value;clearTimeout(searchDelay);searchDelay=setTimeout(render,180);}
});
document.addEventListener('change',async event=>{
  const el=event.target;
  if(el.dataset.libraryFilter){ui[el.dataset.libraryFilter]=el.value;ui.recallIndex=0;ui.recallRevealed=false;if(ui.libraryMode==='recall'&&el.dataset.libraryFilter==='libraryKind'&&!['Questions & answers','Saved for later'].includes(el.value))ui.libraryMode='read';render();}
  if(el.dataset.libraryCheck){toggleArray('checklist',el.dataset.libraryCheck);}
  if(el.dataset.change==='library-expand'){const ids=librarySelection().map(entry=>entry.id);ui.libraryOpen=el.checked?[...new Set([...ui.libraryOpen,...ids])]:ui.libraryOpen.filter(id=>!ids.includes(id));render();}
  if(el.dataset.filter){ui[el.dataset.filter]=el.value;ui.pageNumber=1;render();}
  if(el.dataset.change==='role'){S.role=el.value;persist();render();toast(`Your focus is now ${S.role}.`);}
  if(el.dataset.appStatus){const app=S.applications.find(a=>a.id===el.dataset.appStatus);if(app){app.status=el.value;persist();render();toast('Your next step is up to date.');}}
  if(el.id==='import-file'&&el.files?.[0]){try{if(el.files[0].size>2_000_000)throw new Error('Choose a Culture backup smaller than 2 MB.');const data=JSON.parse(await el.files[0].text());if(data.app!=='culture'||data.version!==1)throw new Error('Please choose an exported Culture backup.');const incoming=normalizeState(data);window.pendingCultureImport=incoming;openModal('Bring your progress here?',`<p>This backup contains ${incoming.reviewed.length} reviewed questions, ${incoming.days.length} study days, and ${incoming.applications.length} opportunities. Importing it replaces the progress currently saved on this browser and clears any unfinished mock here.</p><div class="modal-actions">${btn('Keep current progress','close-modal','left','secondary')}${btn('Import this backup','accept-import','upload')}</div>`);}catch(err){toast(err.message||'This file could not be imported.');el.value='';}}
});
document.addEventListener('submit',event=>{
  if(event.target.id==='global-search'){event.preventDefault();const query=new FormData(event.target).get('query');resetLibrary();ui.librarySearch=String(query||'');navigate('library');}
  if(event.target.id==='mock-setup'){event.preventDefault();const form=new FormData(event.target),count=Number(form.get('count')),role=String(form.get('role')),level=String(form.get('level'));const qs=selectMock(D.questions,role,level,count);if(!qs.length)return toast('No questions match this combination. Try mixed levels.');mock={id:crypto.randomUUID(),role,ids:qs.map(q=>q.id),index:0,time:Number(form.get('time')),remaining:Number(form.get('time')),draft:'',revealed:false,paused:false,complete:false,answers:[]};persistMock();render();window.scrollTo(0,0);if(qs.length<count)toast(`This combination has ${qs.length} questions. Your session includes all of them.`);}
  if(event.target.id==='application-form'){event.preventDefault();const form=new FormData(event.target),company=String(form.get('company')).trim(),role=String(form.get('role')).trim(),url=String(form.get('url')).trim();if(!company||!role)return document.querySelector('#application-error').textContent='Add a company and role to save this opportunity.';if(url&&!safeUrl(url))return document.querySelector('#application-error').textContent='Use a complete http or https link.';const id=event.target.dataset.id||crypto.randomUUID();const a={id,company,role,url,status:String(form.get('status')),date:String(form.get('date')),next:String(form.get('next')).trim()};S.applications=S.applications.filter(a=>a.id!==id);S.applications.unshift(a);persist();closeModal();render();toast('One thoughtful next step, saved.');}
});
document.addEventListener('toggle',event=>{const el=event.target;if(!el.matches?.('details[data-library-entry]')||!el.isConnected)return;const visible=[...document.querySelectorAll('details[data-library-entry]')];const ids=visible.map(item=>item.dataset.libraryEntry);ui.libraryOpen=[...ui.libraryOpen.filter(id=>!ids.includes(id)),...visible.filter(item=>item.open).map(item=>item.dataset.libraryEntry)];const expand=document.getElementById('library-expand');if(expand)expand.checked=visible.length>0&&visible.every(item=>item.open);},true);
modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&ui.menu){ui.menu=false;render();document.querySelector('.menu-button')?.focus();}if(event.key==='Tab'&&ui.menu&&matchMedia('(max-width:760px)').matches){const els=[...document.querySelectorAll('.sidebar a[href],.sidebar button:not([disabled])')];const first=els[0],last=els.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>{if(modal.open)closeModal();clearTimeout(searchDelay);readHash();render();document.querySelector('#main')?.focus({preventScroll:true});window.scrollTo(0,0);});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&mock&&!mock.complete){mock.paused=true;persistMock();manageTimer();}else if(ui.page==='mock')render();});

function sanitizeProgress(s){const ids=new Set(D.questions.map(q=>q.id));s.reviewed=s.reviewed.filter(id=>ids.has(id));s.saved=s.saved.filter(id=>ids.has(id));s.days=s.days.filter(d=>D.journey.days.some(day=>String(day.day)===d));s.checklist=s.checklist.filter(id=>D.journey.checklist.some(c=>c.id===id));s.librarySaved=(s.librarySaved||[]).filter(id=>D.library.some(entry=>entry.id===id&&!entry.questionId));return s;}
matchMedia('(max-width:760px)').addEventListener('change',()=>{if(D){ui.menu=false;render();}});

async function start(){
  try{
    const names=['questions','sources','companies','company-sources','journey'];
    const [questions,sources,companies,companySources,journey]=await Promise.all(names.map(async name=>{const r=await fetch(`/content/${name}.json`);if(!r.ok)throw new Error(`Unable to load ${name}.`);return r.json();}));
    D={questions,sources,companies,companySources,journey,allSources:[...sources,...companySources]};D.library=buildStudyIndex(D);
    try{const saved=localStorage.getItem(STORAGE_KEY);S=saved?normalizeState(JSON.parse(saved)):structuredClone(DEFAULT_STATE);}catch{S=structuredClone(DEFAULT_STATE);storageAvailable=false;}
    S=sanitizeProgress(S);const qids=new Set(questions.map(q=>q.id));
    try{const m=JSON.parse(localStorage.getItem(STORAGE_KEY+'.mock')||'null');if(m&&Array.isArray(m.ids)&&m.ids.length&&m.ids.every(id=>qids.has(id))&&Array.isArray(m.answers)&&Number.isInteger(m.index)&&m.index>=0&&m.index<=m.ids.length&&ROLES.includes(m.role)){mock=m;if(!mock.complete)mock.paused=true;}}catch{}
    readHash();render();
  }catch(error){root.innerHTML=`<div class="error-page"><img src="/favicon.svg" width="45" alt="Culture"><h1>Let’s try that again.</h1><p>The study content couldn’t load. Check your connection and reload the page.</p><p>${e(error.message)}</p><button class="btn" data-action="reload">Reload page</button></div>`;root.querySelector('button').addEventListener('click',()=>location.reload());}
}
function resetLibrary() {
  Object.assign(ui, { librarySearch: '', libraryKind: 'All material', libraryTopic: 'All topics', libraryRole: 'All roles', libraryDifficulty: 'All levels', libraryMode: 'read', recallIndex: 0, recallRevealed: false });
}
function librarySelection() {
  return filterStudyIndex(D.library, { search: ui.librarySearch, kind: ui.libraryKind, topic: ui.libraryTopic, role: ui.libraryRole, difficulty: ui.libraryDifficulty }, S);
}
function shelfId(topic) { return `shelf-${topic.toLowerCase().replace(/[^a-z0-9]+/g, '-')}`; }
function libraryPage() {
  const entries = librarySelection();
  const topics = [...new Set(D.library.map(entry => entry.topic))];
  const groups = topics.map(topic => ({ topic, entries: entries.filter(entry => entry.topic === topic) })).filter(group => group.entries.length);
  const allOpen = entries.length > 0 && entries.every(entry => ui.libraryOpen.includes(entry.id));
  const savedCount = D.library.filter(entry => isLibrarySaved(entry, S)).length;
  return `${heading('Your always-open corner of microbiology', 'The study library', 'Everything in one place. Read any topic, remember the essentials, and return whenever you want. No schedule, no targets.', btn('Print this selection', 'library-print', 'print', 'secondary'))}
    <section class="library-welcome" aria-label="Ways to use the library">
      <div><span class="label">ONE SHELF. YOUR OWN PACE.</span><h2>Refer. Understand. Remember. Revisit.</h2><p>All ${D.questions.length} questions, your project stories, HR answers, company prep, and ${D.allSources.length} references live here.</p></div>
      <span class="library-welcome-icon">${I('book',42)}</span>
    </section>
    <section class="card library-controls" aria-label="Find study material">
      <label for="library-search">Find anything on your shelf</label>
      <div class="library-search-row"><div class="search-field">${I('search',17)}<input id="library-search" data-input="library-search" value="${e(ui.librarySearch)}" placeholder="Try PCR, informed consent, Eurofins, or a project…" autocomplete="off"></div><button id="library-saved-button" type="button" class="btn ${ui.libraryKind==='Saved for later'?'':'secondary'}" data-action="library-saved" aria-pressed="${ui.libraryKind==='Saved for later'}">${I('save',15)} Saved (${savedCount})</button></div>
      <div class="library-filter-row"><div><label for="library-kind">Material</label><select id="library-kind" data-library-filter="libraryKind">${option(['All material',...LIBRARY_KINDS,'Saved for later'],ui.libraryKind)}</select></div><div><label for="library-topic">Topic</label><select id="library-topic" data-library-filter="libraryTopic">${option(['All topics',...topics],ui.libraryTopic)}</select></div><div><label for="library-role">Role</label><select id="library-role" data-library-filter="libraryRole">${option(['All roles',...ROLES],ui.libraryRole)}</select></div><div><label for="library-level">Question level</label><select id="library-level" data-library-filter="libraryDifficulty">${option(['All levels','Basic','Intermediate','Advanced'],ui.libraryDifficulty)}</select></div></div>
      <div class="library-control-footer"><div class="library-modes" aria-label="How you want to study">${[['read','Read & refer','book'],['revise','Quick revision','leaf'],['recall','Recall cards','spark']].map(([mode,name,icon])=>`<button id="library-mode-${mode}" type="button" class="tab ${ui.libraryMode===mode?'active':''}" data-action="library-mode" data-mode="${mode}" aria-pressed="${ui.libraryMode===mode}">${I(icon,13)} ${name}</button>`).join('')}</div><button type="button" class="text-btn" data-action="library-clear">Clear filters</button></div>
    </section>
    <div class="library-results-bar"><p id="library-results-count" role="status" aria-live="polite">${entries.length} ${entries.length===1?'item':'items'}${ui.librarySearch?` matching “${e(ui.librarySearch)}”`:''}${ui.libraryKind==='Saved for later'?' on your revision shelf':''}</p>${ui.libraryMode==='read'&&entries.length?`<label class="library-expand-label"><input id="library-expand" type="checkbox" data-change="library-expand" ${allOpen?'checked':''}> Open all items</label>`:''}</div>
    ${ui.libraryMode==='recall'?libraryRecall(entries):entries.length?`<div class="library-layout"><aside class="library-contents" aria-label="Jump to a section"><span class="label">ON THIS SHELF</span>${groups.map(group=>`<button type="button" data-action="library-jump" data-topic="${e(group.topic)}">${e(group.topic)}<span>${group.entries.length}</span></button>`).join('')}<div class="library-side-note">${I('leaf',18)}<p>No prerequisites. Open what helps, and return whenever you like.</p></div></aside><div class="library-groups">${groups.map(group=>`<section class="library-group" aria-labelledby="${shelfId(group.topic)}"><div class="section-heading"><h2 id="${shelfId(group.topic)}" tabindex="-1">${e(group.topic)}</h2><small>${group.entries.length} ${group.entries.length===1?'item':'items'}</small></div>${group.entries.map(libraryEntry).join('')}</section>`).join('')}</div></div>`:libraryEmpty()}
    <button type="button" class="library-back-top" data-action="library-top">${I('search',14)} Find a topic</button><div class="library-bottom-link"><p>Prefer a focused workspace?</p><a href="#questions">Question bank</a><a href="#story">My story</a><a href="#companies">Company room</a><a href="#mock">Mock interview</a><a href="#applications">Job tracker</a></div>`;
}
function libraryEmpty() {
  return `<div class="empty">${I(ui.libraryKind==='Saved for later'?'save':'search',30)}<h3>${ui.libraryKind==='Saved for later'?'A shelf for the things you want to keep.':'Let’s look a little wider.'}</h3><p>${ui.libraryKind==='Saved for later'?'Use the bookmark beside any item to bring it here. Your question-bank bookmarks appear here too.':'No material matches this combination. Try a shorter search or clear a filter.'}</p>${btn('Browse all material','library-clear','book','secondary')}</div>`;
}
function libraryEntry(entry) {
  const saved = isLibrarySaved(entry,S);
  const open = ui.libraryPrint || ui.libraryMode==='revise' || ui.libraryOpen.includes(entry.id);
  return `<article class="library-entry card" id="entry-${entry.id.replace(/:/g,'-')}"><div class="library-entry-bar"><div>${pill(entry.kind)}${entry.difficulty?pill(entry.difficulty,entry.difficulty):''}${entry.questionId&&S.reviewed.includes(entry.questionId)?pill('Reviewed'):''}</div><button type="button" class="icon-btn ${saved?'selected':''}" data-action="library-save" data-id="${e(entry.id)}" aria-label="${saved?'Unsave':'Save'} ${e(entry.title)}" aria-pressed="${saved}">${I('save',17)}</button></div><details data-library-entry="${e(entry.id)}" ${open?'open':''}><summary><h3>${e(entry.title)}</h3><span>${I('down',16)}</span></summary><div class="library-entry-body">${libraryEntryBody(entry)}</div></details></article>`;
}
function libraryEntryBody(entry) {
  const d=entry.data;
  if(entry.questionId) {
    const quick=ui.libraryMode==='revise'&&!ui.libraryPrint;
    return `${quick?'':`<p class="library-answer">${e(d.answer)}</p>`}<div class="key-points"><strong>${quick?'Remember these points':'The essentials'}</strong><ul>${d.keyPoints.map(point=>`<li>${e(point)}</li>`).join('')}</ul></div>${quick?`<details class="library-original"><summary>Read the full answer</summary><p>${e(d.answer)}</p></details>`:''}<div class="pitfall"><strong>Watch out:</strong> ${e(d.pitfall)}</div><p class="follow-up"><strong>Think one step further:</strong> ${e(d.followUp)}</p>${sourceLinks(d.sourceIds)}<div class="answer-actions">${btn(S.reviewed.includes(d.id)?'Reviewed — undo':'Mark as reviewed','review-question','check','soft',`data-id="${d.id}"`)}<span class="library-coaching-note">${d.category==='HR & communication'?'Make the wording your own and use real examples.':'Explain the idea in your own words before memorizing it.'}</span></div>`;
  }
  if(entry.kind==='Project stories') {
    return `<p>${e(d.answer)}</p><div class="key-points"><strong>A way to remember the story</strong><p>Aim → what I actually did → verified finding → limitation → learning.</p></div>${d.followUps.map(f=>`<div class="library-followup"><h4>${e(f.question)}</h4><p>${e(f.answer)}</p></div>`).join('')}<div class="honesty">${e(d.honestyNote)}</div>${libraryNote(entry,'My verified project details','My method, contribution, actual findings, and one limitation…')}`;
  }
  if(entry.id==='intro') return `<p>${e(d.pitch)}</p><div class="honesty">${e(d.closer)}</div><p class="library-coaching-note">Personalized from the supplied CV. Rehearse naturally and verify the details against your own records.</p>`;
  if(entry.id==='checklist') return `<p>Use whatever is helpful before a conversation. This is a practical reference, not a study target.</p><ul class="library-checklist">${d.map(item=>`<li><label><input type="checkbox" data-library-check="${item.id}" ${S.checklist.includes(item.id)?'checked':''}><span>${e(item.text)}</span></label></li>`).join('')}</ul>`;
  if(entry.id==='notebook') return `<p>Keep an explanation that finally clicked, a useful memory cue, or a question to revisit. These notes stay on this browser and are included in your backup.</p>${libraryNote(entry,'My notes','Things I want to remember…')}`;
  if(entry.kind==='CV & HR') return `<p>${e(d.answer)}</p><div class="honesty">${e(d.tip)}</div><p class="library-coaching-note">Original coaching based on the CV. These are rehearsal prompts, not a script or an invented personal experience.</p>`;
  if(entry.kind==='Role guides') return `<p>${e(d.description)}</p><div class="key-points"><strong>Keep these areas in mind</strong><ul>${d.focus.map(point=>`<li>${e(point)}</li>`).join('')}</ul></div><div class="mini-label">Useful job-search terms</div><div class="topic-chips">${d.searchTerms.map(term=>pill(term)).join('')}</div><div class="honesty">${e(d.gap)}</div>`;
  if(entry.kind==='References') return `<div class="report-meta">${e(d.organization)} · ${e(d.type)}</div><p>${e(d.note)}</p>${link('Read the original source',d.url)}`;
  if(entry.kind==='Company prep') return `<p>${e(d.overview)}</p><p class="report-meta">${e(d.locationNote)}</p><div class="topic-chips">${d.practiceTopics.map(topic=>pill(topic)).join('')}</div><div class="honesty">${e(d.evidenceNote)}</div><h4 class="library-subheading">Suggested role practice</h4><p class="library-coaching-note">${e(d.practiceLabel)}</p>${d.practiceQuestions.map(q=>`<div class="library-followup"><h4>${e(q.question)}</h4><p>${e(q.answer)}</p></div>`).join('')}<div class="sources-line">${(d.practiceSourceUrls||[]).map((url,i)=>link(`Practice reference ${i+1}`,url)).join('')}</div>${d.reports.length?`<h4 class="library-subheading">Reported experiences · anecdotal</h4>${d.reports.map(report=>`<section class="library-report"><h4>${e(report.title)}</h4><p class="report-meta">${e(report.platform)} · ${e(report.date)}<br>${e(report.role)}</p><p>${e(report.summary)}</p>${(report.questions||[]).map(q=>`<div class="library-followup"><span class="label">Reported topic · practice prompt and suggested answer</span><h4>${e(q.question)}</h4><p>${e(q.answer)}</p></div>`).join('')}<div class="honesty">${e(report.caveat)}</div>${link('Read the original account',report.url)}</section>`).join('')}`:''}<div class="answer-actions">${link('Official company careers / role page',d.officialUrl)}<a class="text-btn" href="#companies/${d.id}">Open the company room ${I('arrow',13)}</a></div>${libraryNote(entry,'My own interview notes','Role, date, actual questions, and what I learned…')}`;
  return '';
}
function libraryNote(entry,label,placeholder) {
  return `<label class="mini-label" for="library-note-${entry.noteKey}">${e(label)} · saved on this browser</label><textarea class="notepad" id="library-note-${entry.noteKey}" data-note="${e(entry.noteKey)}" placeholder="${e(placeholder)}">${e(S.notes[entry.noteKey]||'')}</textarea>`;
}
function libraryRecall(entries) {
  const cards=entries.filter(entry=>entry.questionId);
  if(!cards.length) return `<div class="empty">${I('spark',30)}<h3>A question is a good place to start.</h3><p>Recall cards use the questions in your selection. Clear your filters to explore the full question bank.</p>${btn('Show recall questions','library-recall','spark','secondary')}</div>`;
  ui.recallIndex=Math.max(0,Math.min(ui.recallIndex,cards.length-1));
  const entry=cards[ui.recallIndex],q=entry.data,saved=isLibrarySaved(entry,S);
  return `<section class="library-recall" aria-label="Recall practice"><div class="library-recall-heading"><span class="day-badge">CARD ${ui.recallIndex+1} OF ${cards.length}</span><p>Try answering before you peek. Nothing is timed or scored.</p></div><article class="card"><div class="library-entry-bar"><div>${pill(q.category)}${pill(q.difficulty,q.difficulty)}</div><button type="button" class="icon-btn ${saved?'selected':''}" data-action="library-save" data-id="${entry.id}" aria-label="${saved?'Unsave':'Save'} ${e(q.title)}" aria-pressed="${saved}">${I('save',18)}</button></div><h2>${e(q.title)}</h2><p class="library-recall-hint">Pause for a moment. What is the idea, and what would you say in an interview?</p>${ui.recallRevealed?`<div class="library-recall-answer"><p>${e(q.answer)}</p><div class="key-points"><strong>Check your recall</strong><ul>${q.keyPoints.map(point=>`<li>${e(point)}</li>`).join('')}</ul></div><div class="pitfall">${e(q.pitfall)}</div><p class="follow-up"><strong>Follow-up:</strong> ${e(q.followUp)}</p>${sourceLinks(q.sourceIds)}<button class="text-btn" type="button" data-action="library-save" data-id="${entry.id}">${I('save',14)} ${saved?'Saved for later — remove':'Keep this for revision'}</button></div>`:btn('Reveal the answer','library-reveal','book','secondary')}<div class="library-recall-navigation">${btn('Previous card','library-previous','left','secondary small',ui.recallIndex===0?'disabled':'')}<button class="text-btn" type="button" data-action="library-hide">${ui.recallRevealed?'Try this card again':'Start this card again'}</button>${btn(ui.recallIndex===cards.length-1?'Back to first card':'Next card','library-next','arrow','small')}</div></article></section>`;
}
start();
